import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s6-u08")
C = "B1-B2"

L(1, "Kennen vs. weten; leren vs. studeren", "Verbos fáceis de confundir.",
  ["Distinguir pares de verbos frequentemente confundidos"],
  vocab=[V("v-kennen-weten","kennen / weten","conhecer / saber","expression"), V("v-leren-studeren","leren / studeren","aprender / estudar (curso)","expression"),
         V("v-lenen-uitlenen","lenen / uitlenen","pedir emprestado / emprestar","expression"), V("v-zetten-leggen","zetten / leggen","pôr (de pé) / pôr (deitado)","expression")],
  ex=[("Ik ken hem, maar ik weet zijn naam niet.","Conheço-o, mas não sei o nome dele."),("Ze studeert rechten en leert Spaans.","Ela estuda Direito e está a aprender espanhol."),("Mag ik je fiets lenen?","Posso pedir-te a bicicleta emprestada?"),("Zet de fles op tafel en leg het boek ernaast.","Põe a garrafa na mesa e pousa o livro ao lado.")],
  gram=[G("g-verwarrende-paren","Pares confusos","**kennen** + pessoa/lugar/coisa (conhecer); **weten** + facto/oração (saber): *Ik weet dat…* **studeren** = estudar um curso; **leren** = aprender/estudar para algo: *Ik leer voor mijn toets.* **lenen** = pedir emprestado; **uitlenen** = emprestar. **zetten** (pôr de pé) / **leggen** (pôr deitado).",
    [("Weet jij waar het station is?","Sabes onde fica a estação?"),("Ken je Utrecht?","Conheces Utrecht?")],
    "Em português «emprestar» e «pedir emprestado» são diferentes; em neerlandês também, mas muitos aprendentes trocam.")],
  review=["v-kennen","v-weten","v-leren","v-studeren","v-lenen"],
  cefr=C, exs=[
    MA([("kennen","conhecer"),("weten","saber"),("lenen","pedir emprestado"),("uitlenen","emprestar"),("leggen","pôr deitado")], "Pares.", ["v-kennen-weten","v-lenen-uitlenen","v-zetten-leggen"]),
    FB("Ik ___ niet waar hij woont.", ["weet"], "Facto → weten.", ["v-kennen-weten"], choices=["weet","ken","leer"], tr="Não sei onde ele mora."),
    FB("___ jij mijn broer?", ["Ken"], "Pessoa → kennen.", ["v-kennen-weten"], choices=["Ken","Weet","Leer"], tr="Conheces o meu irmão?"),
    FB("Mijn zus ___ geneeskunde in Leiden.", ["studeert"], "Curso → studeren.", ["v-leren-studeren"], choices=["studeert","leert","weet"], tr="A minha irmã estuda medicina em Leiden."),
    FB("Kun je me tien euro ___?", ["lenen","uitlenen"], "Emprestar-me → (uit)lenen aan mij.", ["v-lenen-uitlenen"], choices=["lenen","huren","kopen"], tr="Podes emprestar-me dez euros?"),
    FE(["Ik","ken","dat","hij","ziek","is."], 1, "weet", "Facto (dat…) → weten.", ["v-kennen-weten"]),
    FE(["Ik","heb","mijn","fiets","aan","Tom","geleend."], 6, "uitgeleend", "Dar emprestado = uitlenen: Ik heb mijn fiets aan Tom uitgeleend.", ["v-lenen-uitlenen"]),
    MC("Uma garrafa fica «de pé» na mesa. Usa…", ["*zetten","leggen|Seria deitada.","hangen|Seria pendurada."], "Posição.", ["v-zetten-leggen"]),
    TR("pt-nl","Conheço-o, mas não sei o nome dele.", ["Ik ken hem(,) maar ik weet zijn naam niet"], "kennen/weten.", ["v-kennen-weten"]),
    LI("Leg je telefoon maar op tafel.", ["Leg je telefoon maar op tafel"], "Pousa o telemóvel na mesa.", "leggen.", ["v-zetten-leggen"]),
  ], diff=5, mins=7)

L(2, "Sinónimos próximos", "mooi/prachtig, groot/enorm, belangrijk/essentieel",
  ["Escolher entre sinónimos com intensidade diferente"],
  vocab=[V("v-prachtig","prachtig","magnífico","adjective"), V("v-enorm","enorm","enorme","adjective"),
         V("v-essentieel","essentieel","essencial","adjective"), V("v-schitterend","schitterend","esplêndido","adjective"),
         V("v-gering","gering","reduzido|pequeno (formal)","adjective")],
  ex=[("Het uitzicht is prachtig.","A vista é magnífica."),("Het verschil is enorm.","A diferença é enorme."),("Goede communicatie is essentieel.","Uma boa comunicação é essencial."),("De kans is gering.","A probabilidade é reduzida.")],
  gram=[G("g-intensiteit","Intensidade","Muitos adjetivos têm graus: **mooi < prachtig < schitterend**; **groot < enorm < gigantisch**; **belangrijk < essentieel/cruciaal**; **klein < gering** (formal). Escolher a palavra certa evita exageros e repetições.",
    [("Het is niet alleen mooi, het is werkelijk prachtig.","Não é só bonito, é verdadeiramente magnífico.")])],
  review=["v-mooi","v-groot","v-belangrijk","v-klein"],
  cefr=C, exs=[
    MA([("prachtig","magnífico"),("enorm","enorme"),("essentieel","essencial"),("schitterend","esplêndido"),("gering","reduzido")], "Sinónimos.", ["v-prachtig","v-enorm","v-essentieel","v-schitterend","v-gering"]),
    MC("Qual é o mais intenso?", ["*schitterend","mooi|Neutro.","aardig|Fraco."], "Escala.", ["v-schitterend"]),
    MC("Num relatório formal, «a hipótese é pequena» fica melhor como…", ["*De kans is gering.","De kans is klein-klein.|Não.","De kans is mini.|Coloquial."], "Registo.", ["v-gering"]),
    TR("nl-pt","Goede communicatie is essentieel.", ["Uma boa comunicação é essencial","A boa comunicação é essencial"], "essentieel.", ["v-essentieel"]),
    TR("pt-nl","A diferença é enorme.", ["Het verschil is enorm","Het verschil is heel groot"], "enorm.", ["v-enorm"]),
    TR("pt-nl","A vista é magnífica.", ["Het uitzicht is prachtig","Het uitzicht is schitterend"], "prachtig.", ["v-prachtig"]),
    FE(["Het","was","een","prachtige","dag","en","een","prachtige","avond","en","een","prachtige","nacht."], 11, "schitterende", "Varie: evite repetir o mesmo adjetivo (ex.: schitterende).", ["v-schitterend"]),
    LI("Het verschil tussen de twee is enorm.", ["Het verschil tussen de twee is enorm"], "A diferença entre os dois é enorme.", "enorm.", ["v-enorm"]),
    FB("Voor dit werk is ervaring ___.", ["essentieel"], "Essencial.", ["v-essentieel"], choices=["essentieel","gering","prachtig"], tr="Para este trabalho a experiência é essencial."),
    WO("A probabilidade é reduzida.", ["De","kans","is","gering"], "gering.", ["v-gering"]),
  ], diff=5, mins=6)

L(3, "Verbos de dizer", "zeggen, vertellen, praten, spreken, melden, beweren",
  ["Escolher o verbo de comunicação certo"],
  vocab=[V("v-vertellen","vertellen","contar","verb"), V("v-noemen","noemen","mencionar|chamar","verb"),
         V("v-opmerken","opmerken","observar|comentar","verb")],
  ex=[("Hij vertelde een grappig verhaal.","Ele contou uma história engraçada."),("U moet een verhuizing melden bij de gemeente.","Tem de comunicar uma mudança à câmara."),("Hij beweert dat hij niets wist.","Ele afirma que não sabia de nada."),("Ze noemde drie voorbeelden.","Ela mencionou três exemplos.")],
  gram=[G("g-zeggen-vertellen","Verbos de dizer","**zeggen** + o que se diz (*zeggen dat…*); **vertellen** + história/informação a alguém; **praten** = conversar (*praten over*); **spreken** = falar (língua, formal); **melden** = comunicar oficialmente; **beweren** = afirmar (com dúvida); **noemen** = mencionar ou chamar (*Ze noemen hem Bas*).",
    [("Volgens de krant beweert de minister dat…","Segundo o jornal, o ministro afirma que…")])],
  review=["v-beweren","v-melden","v-zeggen","v-praten-over","v-spreken"],
  cefr=C, exs=[
    MA([("vertellen","contar"),("melden","comunicar"),("beweren","afirmar"),("noemen","mencionar"),("opmerken","observar")], "Verbos de dizer.", ["v-vertellen","v-melden","v-beweren","v-noemen","v-opmerken"]),
    FB("Opa ___ altijd verhalen over de oorlog.", ["vertelt","vertelde"], "Contar histórias.", ["v-vertellen"], choices=["vertelt","zegt","spreekt"], tr="O avô conta sempre histórias sobre a guerra."),
    FB("Je moet de schade binnen 24 uur ___.", ["melden"], "Comunicar oficialmente.", ["v-melden"], choices=["melden","vertellen","praten"], tr="Tens de comunicar o dano em 24 horas."),
    FB("Hij ___ dat hij de beste is, maar niemand gelooft hem.", ["beweert"], "Afirmar (com dúvida).", ["v-beweren"], choices=["beweert","meldt","vertelt"], tr="Ele afirma que é o melhor, mas ninguém acredita."),
    FE(["Kun","je","mij","zeggen","een","verhaal?"], 3, "vertellen", "Contar uma história = een verhaal vertellen.", ["v-vertellen"]),
    MC("«Ze noemen hem Bas» significa…", ["*Chamam-lhe Bas","Mencionam o Bas|Neste contexto é «chamar».","Ligam ao Bas|Isso é «bellen»."], "noemen.", ["v-noemen"]),
    TR("pt-nl","Ela mencionou três exemplos.", ["Ze noemde drie voorbeelden","Zij noemde drie voorbeelden"], "noemen.", ["v-noemen"]),
    TR("nl-pt","Hij beweert dat hij niets wist.", ["Ele afirma que não sabia de nada","Ele alega que não sabia nada"], "beweren.", ["v-beweren"]),
    LI("Mag ik nog iets opmerken over het budget?", ["Mag ik nog iets opmerken over het budget"], "Posso fazer mais uma observação sobre o orçamento?", "opmerken.", ["v-opmerken"]),
    WO("Ele contou uma história engraçada.", ["Hij","vertelde","een","grappig","verhaal"], "het verhaal → grappig.", ["v-vertellen"]),
  ], diff=5, mins=7)

L(4, "Palavras pequenas, grande diferença", "al/pas/nog, ook/zelfs, maar/alleen",
  ["Usar advérbios que mudam o sentido da frase"],
  vocab=[V("v-pas-adv","pas","só (mais tarde/menos do que esperado)","adverb",note="Hij is pas 18. / Ik kom pas om tien uur."), V("v-zelfs","zelfs","até|mesmo","adverb")],
  ex=[("Hij is pas achttien.","Ele só tem dezoito anos."),("Ik kom pas om tien uur.","Só chego às dez."),("Zelfs mijn oma heeft een smartphone.","Até a minha avó tem smartphone."),("Het regent nog steeds.","Ainda está a chover.")],
  gram=[G("g-al-pas","Al vs. pas","**al** = já (mais cedo/mais do que esperado): *Hij is **al** dertig.* **pas** = só (mais tarde/menos do que esperado): *Hij is **pas** twintig.* *Ik kom **pas** om tien uur* (só às dez, tarde). **zelfs** = até (surpresa).",
    [("Ben je al klaar? Ik ben pas begonnen!","Já acabaste? Eu só agora comecei!")],
    "«pas» não tem tradução direta: corresponde a «só» com ideia de tarde ou pouco.")],
  review=["v-nog-steeds","v-al","v-nog","v-ook","v-alleen-maar"],
  cefr=C, exs=[
    MA([("pas","só (tarde/pouco)"),("zelfs","até"),("nog steeds","ainda"),("alleen maar","apenas")], "Pequenas palavras.", ["v-pas-adv","v-zelfs","v-nog-steeds","v-alleen-maar"]),
    FB("Hij is ___ achttien, maar hij woont al alleen.", ["pas"], "Pouco (para a idade).", ["v-pas-adv"], choices=["pas","al","zelfs"], tr="Ele só tem dezoito anos, mas já mora sozinho."),
    FB("Ben je ___ klaar? Dat ging snel!", ["al"], "Mais cedo do que esperado.", ["v-al"], choices=["al","pas","nog steeds"], tr="Já acabaste? Foi rápido!"),
    FB("___ mijn oma gebruikt WhatsApp.", ["Zelfs"], "Surpresa.", ["v-zelfs"], choices=["Zelfs","Pas","Nog"], tr="Até a minha avó usa WhatsApp."),
    TR("pt-nl","Só chego às dez.", ["Ik kom pas om tien uur","Ik ben er pas om tien uur"], "pas = só (tarde).", ["v-pas-adv"]),
    TR("pt-nl","Ainda está a chover.", ["Het regent nog steeds","Het regent nog altijd"], "nog steeds.", ["v-nog-steeds"]),
    MC("«Ik heb pas twee hoofdstukken gelezen» sugere que…", ["*leu pouco (menos do que devia)","leu muito|Ao contrário.","acabou o livro|Não."], "pas.", ["v-pas-adv"]),
    FE(["Hij","is","al","twintig,","heel","jong","voor","een","directeur."], 2, "pas", "Pouco para a função → pas twintig.", ["v-pas-adv"]),
    LI("Ik ben pas net begonnen.", ["Ik ben pas net begonnen"], "Só agora comecei.", "pas net.", ["v-pas-adv"]),
    TR("nl-pt","Het kost alleen maar vijf euro.", ["Custa apenas cinco euros","Só custa cinco euros"], "alleen maar.", ["v-alleen-maar"]),
  ], diff=5, mins=6)

L(5, "Conotação: positivo, neutro, negativo", "zuinig/gierig, direct/bot, rustig/saai",
  ["Escolher palavras com a conotação adequada"],
  vocab=[V("v-gierig","gierig","forreta","adjective"), V("v-saai","saai","aborrecido","adjective"),
         V("v-eigenwijs","eigenwijs","teimoso","adjective"), V("v-vastberaden","vastberaden","determinado","adjective"),
         V("v-nieuwsgierig","nieuwsgierig","curioso","adjective")],
  ex=[("Hij is niet zuinig, hij is gewoon gierig!","Ele não é poupado, é simplesmente forreta!"),("Het dorp is rustig, maar niet saai.","A aldeia é sossegada, mas não aborrecida."),("Ze is eigenwijs.","Ela é teimosa."),("Hij is vastberaden om te slagen.","Ele está determinado a ter sucesso.")],
  gram=[G("g-connotatie","Conotação","O mesmo traço pode descrever-se de forma positiva ou negativa: **zuinig** (+) / **gierig** (−); **direct** (+/neutro) / **bot** (−); **rustig** (+) / **saai** (−); **vastberaden** (+) / **eigenwijs** (−). Escolha a palavra conforme a intenção — sobretudo em feedback e cartas de referência.",
    [("Ze is nieuwsgierig (+) — ze is bemoeizuchtig (−).","Ela é curiosa — ela é intrometida.")])],
  review=["v-zuinig","v-direct","v-bot","v-rustig"],
  cefr=C, exs=[
    MA([("gierig","forreta"),("saai","aborrecido"),("eigenwijs","teimoso"),("vastberaden","determinado"),("nieuwsgierig","curioso")], "Conotação.", ["v-gierig","v-saai","v-eigenwijs","v-vastberaden","v-nieuwsgierig"]),
    MC("Versão positiva de «gierig»:", ["*zuinig","bot|Outra característica.","saai|Outra característica."], "+/−.", ["v-gierig"]),
    MC("Versão negativa de «vastberaden»:", ["*eigenwijs","nieuwsgierig|Outra característica.","rustig|Outra característica."], "+/−.", ["v-eigenwijs"]),
    MC("Numa carta de referência, para um candidato que insiste muito nas suas ideias, escreve…", ["*Hij is vastberaden.","Hij is eigenwijs.|Negativo.","Hij is bot.|Negativo."], "Tom positivo.", ["v-vastberaden"]),
    TR("pt-nl","A aldeia é sossegada, mas não aborrecida.", ["Het dorp is rustig(,) maar niet saai"], "rustig/saai.", ["v-saai"]),
    TR("nl-pt","Ze is eigenwijs.", ["Ela é teimosa","Ela é cabeça-dura"], "eigenwijs.", ["v-eigenwijs"]),
    FE(["Zij","is","een","nieuwsgierige","en","slim","meisje."], 3, "nieuwsgierig", "het meisje → een nieuwsgierig en slim meisje.", ["v-nieuwsgierig"]),
    LI("Ik ben benieuwd hoe het afloopt.", ["Ik ben benieuwd hoe het afloopt"], "Estou curioso para saber como acaba.", "benieuwd (+) = curioso por saber.", ["v-nieuwsgierig"]),
    FB("Hij geeft nooit iets weg, hij is echt ___.", ["gierig"], "Negativo.", ["v-gierig"], choices=["gierig","zuinig","vastberaden"], tr="Ele nunca dá nada, é mesmo forreta."),
    SW("Descreva um colega de forma positiva (2 frases), escolhendo palavras com conotação positiva.", ["Mijn collega is direct en vastberaden. Ze is ook zuinig met het budget en altijd nieuwsgierig naar nieuwe ideeën."], ["Pelo menos 3 adjetivos positivos", "Nenhum adjetivo negativo", "Concordância (-e) correta"], 15, "Tom positivo.", ["v-vastberaden","v-nieuwsgierig"]),
  ], diff=5, mins=7)

W()
